mapper.insert:
INSERT INTO settings (s_key, s_value)
VALUES (#{sKey}, #{sValue})
ON DUPLICATE KEY UPDATE s_value = #{sValue}

mapper.select:
SELECT a_idx, a_id, a_name AS adm_name, a_email, a_addr, a_phone, a_pwd
  FROM admin
 WHERE a_idx = #{aIdx}

mapper.update:
UPDATE admin
   SET a_name  = #{aName},
       a_email = #{aEmail},
       a_phone = #{aPhone}
 WHERE a_idx = #{aIdx}

UPDATE admin
   SET a_pwd = #{aPwd}
 WHERE a_idx = #{aIdx}

UPDATE inquiry_template
   SET t_title   = #{tplTitle},
       t_content = #{tplContent}
 WHERE t_idx = #{tplIdx}
